{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Konklusionen (arbejdsophør giver ikke i sig selv ret) og beskrivelsen af UDK's vurdering stemmer med ekspertrubrikken og vejledningens afsnit 3.4.1.3. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: arbejdets karakter sammenholdes med funktionsnedsættelsen, sagens øvrige oplysninger bruges til at vurdere andre typer arbejde, og skånehensyn/mindre omfang indgår. Eksemplet med ikke-fysisk belastende arbejde er også nævnt."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (hverken lov, bekendtgørelse eller vejledningsafsnit). Det er ren tekst uden henvisninger."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om kilden understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Indholdet svarer til vejledningens afsnit 3.4.1.3. Svaret tilføjer ingen regler, betingelser eller retsvirkninger uden støtte i materialet."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret fastholder, at arbejdsophør ikke i sig selv giver ret, og at ikke-fysisk belastende arbejde kun er et eksempel (\"eksempelvis\"). Skånehensyn og mindre omfang er formuleret som \"eventuelt\"."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Konklusionen følger af de beskrevne vurderingstrin, og de er indbyrdes konsistente."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Modaliteten er præcis. Svaret bruger \"vurderer\", \"kan\", \"eventuelt\" og \"eksempelvis\", og gør ikke vurderingen eller eksemplet til absolutte krav eller automatiske resultater."}
  },
  "xhaile_coverage": {
    "A22": {"label": "yes", "reason": "Svaret behandler situationen, hvor ansøgeren er ophørt i arbejde på grund af funktionsnedsættelsen, og at arbejdets karakter vurderes i forhold til funktionsnedsættelsen. Det inddrager også gener og skånebehov."},
    "A23": {"label": "yes", "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren ud fra sagens øvrige oplysninger kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet i forhold til rubrikken, men svaret nævner ingen kilder. Derfor er C04 not_met, og C05 og C06 er not_assessable."
}

